Cow.syntax:
pub enum Cow<'a, B> where B: 'a + ToOwned + ?Sized {
    Borrowed(&'a B),
    Owned(<B as ToOwned>::Owned),
}

example.code:
use std::borrow::Cow;

fn upper<'a>(text: &'a str) -> Cow<'a, str> {
    if text.chars().all(|c| !c.is_lowercase()) {
        Cow::Borrowed(text)
    } else {
        Cow::Owned(text.to_uppercase())
    }
}

fn main() {
    let mut value = upper("Hello");
    value.to_mut().push('!');
    println!("{value}");
}

