use std::sync::{Arc, RwLock};
use std::thread;

fn main() {
    let value = Arc::new(RwLock::new(0));
    let reader = Arc::clone(&value);
    let handle = thread::spawn(move || {
        let number = reader.read().unwrap();
        println!("{number}");
    });
    {
        let mut number = value.write().unwrap();
        *number += 1;
    }
    handle.join().unwrap();
}

use std::thread;
use std::sync::mpsc;

fn main() {
    let (tx, rx) = mpsc::channel();
    let handle = thread::spawn(move || {
        tx.send(String::from("hello")).unwrap();
    });
    let message = rx.recv().unwrap();
    handle.join().unwrap();
    println!("{message}");
}

